const api=async(path,options={})=>{const bridge=window.ehvSupabaseBridge;if(bridge?.handles(path))return bridge.request(path,options);const base=String(window.__EHV_RUNTIME__?.legacyApiBase||'').replace(/\/$/,'');const r=await fetch(`${base}${path}`,{...options,credentials:'include',headers:{'Content-Type':'application/json',...(state.csrf?{'X-CSRF-Token':state.csrf}:{}),...(options.headers||{})}});if(r.status===204)return null;const data=await r.json();if(!r.ok)throw Error(data.error||'Ein Fehler ist aufgetreten');return data};
