function buildUserMenu(){const plus=state.user.role==='super_admin',partner=['crafts_partner','broker_partner'].includes(state.user.role);$('#user-menu').innerHTML=`<div class="menu-profile"><b>${esc(state.user.name)}</b><span>${esc(state.user.email||'')}</span><span>${esc(labels[state.user.role])}</span></div>${state.supportView?'<button data-menu="support-stop">← Partneransicht beenden</button>':`<button data-menu="account">Mein Profil & Sicherheit</button>${plus?'<button data-menu="roles">Zugangsverwaltung</button><button data-menu="system">Versionsstand, APIs & externe Dienste</button><button data-menu="audit">Änderungsprotokoll</button>':''}${partner?'<button data-menu="workbench">Mein Gewerkecockpit</button>':''}`}<button data-menu="logout">Sicher abmelden</button>`;$('#user-menu').querySelectorAll('[data-menu]').forEach(b=>b.onclick=async()=>{const x=b.dataset.menu;$('#user-menu').hidden=true;if(x==='account')return openAccount();if(x==='system')return openSystemOverview();if(x==='support-stop'){const d=await api('/api/support-view/stop',{method:'POST',body:'{}'});return setup(d.user,d.csrf,d.supportView)}if(x==='logout'){await api('/api/logout',{method:'POST',body:'{}'});location.reload();return}render(x)})}
