const campaignStudioPage=async()=>{const d=await api('/api/campaigns');state.campaignData=d;$('#content').innerHTML=`<div class="page"><section class="hero"><div><span class="kicker">CAMPAIGN INTELLIGENCE</span><h1>Aus Ereignissen werden sichere Servicechancen.</h1><p>Offizielle Quellen, fachliche Einordnung, Zielgruppe, Partnerabdeckung und kontrollierte Freigabe.</p></div><button class="primary" id="new-campaign">+ Kampagne anlegen</button></section><div class="campaign-studio-grid">${d.campaigns.map(c=>`<article class="campaign-card"><div class="card-head"><span class="campaign-type">${campaignType(c.type)}</span><span class="status ${c.gates.ready?'':c.status==='source_review'?'high':'invited'}">${campaignStatus(c.status)}</span></div><h3>${esc(c.title)}</h3><p class="muted">${esc(c.analysis.summary||'Analyse noch nicht erfasst.')}</p><div class="campaign-numbers"><span><b>${c.audience.properties}</b> Immobilien</span><span><b>${c.audience.partners}</b> Partner</span><span><b>${c.audience.dataQuality}%</b> Datenqualität</span></div><div class="gate-line">${[['Quelle',c.gates.source],['Fachlich',c.gates.technical],['Recht',c.gates.legal],['Kommunikation',c.gates.communication]].map(([l,v])=>`<span class="${v?'done':''}">${v?'✓':'○'} ${l}</span>`).join('')}</div><button class="outline open-campaign" data-id="${c.id}">Kampagne bearbeiten</button></article>`).join('')}</div></div>`;document.querySelectorAll('.open-campaign').forEach(b=>b.onclick=()=>openCampaign(b.dataset.id));$('#new-campaign').onclick=()=>newCampaignModal(d)};
