document.addEventListener('click',e=>{const summary=e.target.closest('.trade-grid summary');if(!summary||!state.cockpit)return;e.preventDefault();const name=summary.querySelector('span')?.textContent?.trim(),key=tradeKeys[name];if(key)renderEquipmentCockpit(name,key)});
document.addEventListener('click',e=>{const point=e.target.closest?.('.map-point');if(!point)return;const region=point.querySelector('title')?.textContent?.split(':')[0]?.trim();if(region)openRegionCustomers(region)});
function renderEquipmentCockpit(name,key){const d=state.cockpit,p=d.properties.find(x=>String(x.id)===String(state.cockpitProperty))||d.properties[0],equipment=(d.related[key]||[]).filter(x=>String(x.property_id)===String(p.id)),terms=[name.toLowerCase(),key.replace('_data','').replaceAll('_',' ')],matches=x=>terms.some(t=>JSON.stringify(x).toLowerCase().includes(t)),services=['inspections','reminders','communications'].flatMap(t=>(d.related[t]||[]).filter(x=>String(x.property_id)===String(p.id)&&matches(x)).map(x=>({...x,_source:t}))),docs=(d.related.property_files||[]).filter(x=>String(x.property_id)===String(p.id)&&matches(x));state.equipmentTab=state.equipmentTab||'condition';const tabs=[['condition','Zustand'],['details','Details'],['service','Serviceakte'],['documents','Dokumente'],['history','Verlauf']];const fields=o=>`<div class="info-grid">${Object.entries(o||{}).filter(([k,v])=>v!==null&&v!==''&&!['id','property_id','created_at','updated_at','notificationStatus'].includes(k)).map(([k,v])=>`<div class="info-field"><small>${esc(k.replaceAll('_',' '))}</small><b>${esc(v)}</b></div>`).join('')}</div>`;let body;if(state.equipmentTab==='condition'){const row=equipment[0]||{},year=Number(String(row.year_of_construction||row.year_of_manufacture||'').match(/\d{4}/)?.[0]||0),age=year?new Date().getFullYear()-year:null,last=row.renovation||row.maintance_date||row.maintenance_date||row.last_renovation;body=`<div class="overview-grid"><article class="cockpit-card"><span class="kicker">ANLAGENALTER</span><h3>${age===null?'–':age+' Jahre'}</h3><p class="muted">${year?'Baujahr '+year:'Baujahr nicht dokumentiert'}</p></article><article class="cockpit-card"><span class="kicker">LETZTE MASSNAHME</span><h3>${esc(last||'Nicht dokumentiert')}</h3><p class="muted">Sanierung, Renovierung oder Wartung</p></article><article class="cockpit-card"><span class="kicker">AKTENQUALITÄT</span><h3>${docs.length} Dokumente</h3><p class="muted">${services.length} zuordenbare Serviceeinträge</p></article></div><div class="source-note">KPI-Quelle: Bestandsdaten. Phase-4-Scores werden nach API-Anbindung unverändert übernommen.</div>`}else if(state.equipmentTab==='details')body=equipment.length?equipment.map(fields).join(''):'<div class="cockpit-card empty">Noch keine technischen Angaben vorhanden.</div>';else if(state.equipmentTab==='service')body=`<article class="cockpit-card"><div class="card-head"><h3>Serviceakte ${esc(name)}</h3><span class="status">${services.length}</span></div>${services.length?services.map(fields).join(''):'<p class="muted">Im Altdatenbestand ist kein Serviceeintrag eindeutig diesem Gewerk zugeordnet.</p>'}</article>`;else if(state.equipmentTab==='documents')body=`<article class="cockpit-card"><div class="card-head"><h3>Dokumente ${esc(name)}</h3><span class="status">${docs.length}</span></div>${docs.map(x=>`<div class="document-row"><span class="document-icon">PDF</span><div><b>${esc(x.screen_name||x.pdf_certificate||'Dokument')}</b><small>${x.fileAvailable?'Verfügbar':'Datei fehlt'}</small></div>${x.fileAvailable?`<a class="outline" href="${esc(x.viewUrl)}" target="_blank">Ansehen</a>`:''}</div>`).join('')||'<p class="muted">Kein Dokument ist im Altdatenbestand eindeutig diesem Gewerk zugeordnet.</p>'}</article>`;else body=`<article class="cockpit-card"><h3>Lebenslauf des Gewerks</h3><div class="timeline">${equipment.flatMap(x=>[['Errichtung',x.year_of_construction||x.year_of_manufacture],['Sanierung',x.renovation||x.last_renovation],['Wartung',x.maintance_date||x.maintenance_date]]).filter(([,v])=>v).map(([l,v])=>`<div><i></i><b>${esc(l)}</b><span>${esc(v)}</span></div>`).join('')||'<p class="muted">Noch keine datierten Ereignisse vorhanden.</p>'}</div></article>`;$('#section-label').textContent='GEWERKEAKTE';$('#page-title').textContent=name;$('#content').innerHTML=`<div class="page"><button class="link equipment-back">← Zur Immobilienakte</button><section class="equipment-hero"><div><span class="kicker">${esc(p.address||'IMMOBILIE')}</span><h1>${esc(name)}</h1><p>Vollständige Anlagenakte mit Zustand, Fachdaten, Service und Dokumentation.</p></div></section><nav class="equipment-tabs">${tabs.map(([id,label])=>`<button class="${state.equipmentTab===id?'active':''}" data-equipment-tab="${id}">${label}</button>`).join('')}</nav><section>${body}</section></div>`;$('.equipment-back').onclick=()=>{state.equipmentTab=null;renderCockpit()};document.querySelectorAll('[data-equipment-tab]').forEach(b=>b.onclick=()=>{state.equipmentTab=b.dataset.equipmentTab;renderEquipmentCockpit(name,key)})}
const portfolioPage=async()=>{const d=await api('/api/portfolio/risks');$('#content').innerHTML=`<div class="page"><section class="hero"><div><span class="kicker">BESTAND & RISIKEN</span><h1>Handlungsbedarf erkennen.</h1><p>Priorisierung aus Alter, Wartungsstand und Dokumentation.</p></div></section><div class="kpis">${[['Erfasste Anlagen',d.summary.equipment],['Kritisch',d.summary.critical],['Prüfung empfohlen',d.summary.review]].map(x=>`<div class="card kpi"><span class="muted">${x[0]}</span><div class="value">${x[1]}</div></div>`).join('')}</div><div class="card table-wrap"><table><thead><tr><th>Priorität</th><th>Gewerk</th><th>Immobilie</th><th>Kunde</th><th>Baujahr</th><th>Dokumente</th><th>KPI</th></tr></thead><tbody>${d.items.map(x=>`<tr><td><span class="status ${x.priority==='critical'?'high':x.priority==='review'?'invited':''}">${x.priority==='critical'?'Kritisch':x.priority==='review'?'Prüfen':'Stabil'}</span></td><td><b>${esc(x.trade)}</b></td><td>${esc(x.address||'—')}<br><small>${esc(x.postalCode||'')} ${esc(x.city||'')}</small></td><td>${esc(x.customer||'—')}</td><td>${esc(x.year||'—')}</td><td>${x.documents}</td><td><b>${x.score}%</b><div class="progress"><i style="width:${x.score}%"></i></div></td></tr>`).join('')}</tbody></table></div></div>`};
const campaignsPage=async()=>{const d=await api('/api/campaigns');$('#content').innerHTML=`<div class="page"><section class="hero"><div><span class="kicker">EREIGNISGESTEUERTER SERVICE</span><h1>Aus Signalen werden Cases.</h1><p>Wetter, Wartungsfristen und Datenlücken sicher in Servicebedarf übersetzen.</p></div><button class="primary" id="campaign-new">Kampagne vorbereiten</button></section><div class="grid-2" style="margin-top:20px"><div class="card"><div class="card-head"><h3>Ereignisse & Kampagnen</h3><span class="status">Freigabe erforderlich</span></div>${d.events.map(x=>`<div class="campaign-row"><div><b>${esc(x.type)} · ${esc(x.region)}</b><small>${esc(x.source)}</small></div><span class="status ${x.status==='Entwurf'?'invited':''}">${esc(x.status)}</span></div>`).join('')}</div><div class="card"><h3>Sichere Selektionsregeln</h3>${d.rules.map((x,i)=>`<p><span class="rule-number">${i+1}</span> ${esc(x)}</p>`).join('')}</div></div></div>`;$('#campaign-new').onclick=()=>modal('Kampagne vorbereiten',`<p class="muted">Die Wetter-API ist noch nicht verbunden. Eine Kampagne kann erst nach Regionstreffer, Einwilligungsprüfung, Dublettenprüfung und manueller Freigabe versendet werden.</p><label>Ereignistyp<select><option>Unwetter / Sturm</option><option>Hagel</option><option>Hochwasser</option><option>Wartungsintervall</option></select></label><label>Betroffenes Gewerk<select><option>Dach</option><option>Fassade</option><option>Fenster & Türen</option></select></label><button class="primary" type="button" onclick="this.closest('.modal').remove()">Als Entwurf speichern</button>`)};
openProductionCustomer=renderProductionCustomer;
async function renderProductionCustomer(id){state.cockpit=await api(`/api/production/customers/${encodeURIComponent(id)}`);state.cockpitProperty=state.cockpit.properties[0]?.id;state.cockpitTab='overview';renderCockpit()}
function renderCockpit(){const d=state.cockpit,p=d.properties.find(x=>String(x.id)===String(state.cockpitProperty))||d.properties[0],rows=table=>(d.related[table]||[]).filter(x=>String(x.property_id)===String(p?.id)),person=[d.user.first_name,d.user.last_name].filter(Boolean).join(' ')||d.user.name||'Kundenakte';const tabs=[['overview','Übersicht'],['property','Immobilie'],['trades','Gewerke'],['service','Serviceakte'],['documents','Dokumente'],['contracts','Verträge & Kosten']];$('#section-label').textContent='KUNDEN-DATENBANK';$('#page-title').textContent='360° Kundenakte';$('#content').innerHTML=`<div class="page cockpit"><button class="link cockpit-back">← Zur Kunden-Datenbank</button><section class="cockpit-hero"><div><span class="kicker">VERTRAULICHE KUNDENAKTE</span><h1>${esc(person)}</h1><p>${esc(d.user.email||'')} · ${esc(d.user.phone_number||'')}</p></div><label>Immobilie<select id="cockpit-property">${d.properties.map(x=>`<option value="${x.id}" ${String(x.id)===String(p?.id)?'selected':''}>${esc(x.address||'Immobilie')} · ${esc(x.zip_code||'')} ${esc(x.city||'')}</option>`)}</select></label></section><div class="cockpit-layout"><nav class="cockpit-nav">${tabs.map(([id,name])=>`<button data-tab="${id}" class="${state.cockpitTab===id?'active':''}">${name}</button>`).join('')}</nav><section class="cockpit-content">${cockpitSection(state.cockpitTab,d,p,rows)}</section></div></div>`;$('.cockpit-back').onclick=()=>render('production');$('#cockpit-property').onchange=e=>{state.cockpitProperty=e.target.value;renderCockpit()};document.querySelectorAll('.cockpit-nav button').forEach(b=>b.onclick=()=>{state.cockpitTab=b.dataset.tab;renderCockpit()});const verify=$('#verify-property-address');if(verify)verify.onclick=()=>{modal('Grundbuch lokal auslesen',`<form id="address-verification-form"><div class="source-note">Das Dokument wird ausschließlich lokal mit Tesseract verarbeitet. Der Upload löst noch keine Verifizierung aus.</div><label>Grundbuchauszug<input name="landRegister" type="file" accept="application/pdf,image/png,image/jpeg" required></label><button class="primary">OCR starten und Daten vergleichen</button></form>`);$('#address-verification-form').onsubmit=async e=>{e.preventDefault();const input=e.target.querySelector('[name="landRegister"]'),file=input?.files?.[0];if(!file){toast('Bitte ein Grundbuch auswählen');return}const submit=e.target.querySelector('button.primary');submit.disabled=true;submit.textContent='OCR wird lokal ausgeführt …';let result;try{result=await verifyLandRegisterLocally(file,p.id,`/api/production/properties/${p.id}/address-verification`)}catch(error){submit.disabled=false;submit.textContent='OCR starten und Daten vergleichen';toast(error.message);return}const badge=x=>x==='match'?'Übereinstimmung':x==='review'?'Manuell prüfen':x==='not_detected'?'Nicht erkannt':'Abweichung',checkStatus=x=>`<span class="status ${x.status==='match'?'active':x.status==='mismatch'?'high':''}">${badge(x.status)} · ${x.score||0}%</span>`;modal('OCR-Ergebnis manuell gegenprüfen',`<div class="grid-2"><article class="cockpit-card"><span class="kicker">OCR · GRUNDBUCH ABTEILUNG I</span><h3>${(result.ocrFields.owners||[result.ocrFields.owner]).filter(Boolean).map(esc).join('<br>')||'Kein Eigentümer sicher erkannt'}</h3><p><b>Eigentümerabgleich:</b> ${result.comparison.owner.atLeastOneMatch?'Mindestens ein Eigentümer stimmt überein':'Keine sichere Übereinstimmung'}</p>${checkStatus(result.comparison.owner)}<p>Grundbuchblatt: <b>${esc(result.ocrFields.landRegisterSheet||'–')}</b></p><p>Gemarkung: <b>${esc(result.ocrFields.district||'–')}</b></p><p>Erkannte Adresse: <b>${esc(result.ocrFields.address||'–')}</b><br>${checkStatus(result.comparison.address)}</p><p>Flurstück: <b>${esc(result.ocrFields.parcel||'–')}</b><br>${checkStatus(result.comparison.parcel)}</p></article><article class="cockpit-card"><span class="kicker">DATEN AUS DER APP</span><h3>${esc(result.appData.owner||'Name fehlt')}</h3><p>Immobilienadresse: <b>${esc(result.appData.address||'–')}</b></p><p>Flurstück: <b>${esc(result.appData.parcel||'–')}</b></p><a class="outline" href="${result.document.viewUrl}" target="_blank" rel="noopener">Grundbuch ansehen</a></article></div><form id="manual-address-confirmation" style="margin-top:18px"><div class="source-note"><b>Drei getrennte Freigaben erforderlich</b><br>Die OCR ist eine Vorprüfung. Der Admin bestätigt die Originalurkunde manuell.</div><label class="check-row"><input name="ownerConfirmed" type="checkbox" required> Mindestens ein Eigentümer aus Abteilung I stimmt mit den Kundendaten überein</label><label class="check-row"><input name="addressConfirmed" type="checkbox" required> Die Immobilienadresse stimmt mit der App überein</label><label class="check-row"><input name="parcelConfirmed" type="checkbox" required> Das Flurstück stimmt mit der App überein</label><label>Prüfvermerk<textarea name="note" rows="3" placeholder="Optionaler interner Prüfvermerk"></textarea></label><button class="primary">Fachlich verifiziert freigeben</button></form>`);$('#manual-address-confirmation').onsubmit=async event=>{event.preventDefault();const ownerConfirmed=event.target.querySelector('[name="ownerConfirmed"]').checked,addressConfirmed=event.target.querySelector('[name="addressConfirmed"]').checked,parcelConfirmed=event.target.querySelector('[name="parcelConfirmed"]').checked;if(!ownerConfirmed||!addressConfirmed||!parcelConfirmed)return;await api(`/api/production/properties/${p.id}/address-verification`,{method:'PATCH',body:JSON.stringify({ownerConfirmed,addressConfirmed,parcelConfirmed,note:event.target.querySelector('[name="note"]').value})});closeModal();toast('Immobilie fachlich verifiziert');await renderProductionCustomer(d.user.id);state.cockpitProperty=p.id;state.cockpitTab='property';renderCockpit()}}}}
function cockpitSection(tab,d,p,rows){const field=(label,value)=>value===null||value===''||value===undefined?'':`<div class="info-field"><small>${esc(label)}</small><b>${esc(value)}</b></div>`,grid=o=>`<div class="info-grid">${Object.entries(o||{}).filter(([k,v])=>v!==null&&v!==''&&!['id','property_id','user_id','created_at','updated_at','notificationStatus'].includes(k)).map(([k,v])=>field(k.replaceAll('_',' '),v)).join('')}</div>`,block=(title,items,empty='Keine Angaben vorhanden')=>`<article class="cockpit-card"><div class="card-head"><h3>${title}</h3><span class="status">${items.length} Einträge</span></div>${items.length?items.map(grid).join(''):`<p class="muted">${empty}</p>`}</article>`;if(!p)return '<div class="card empty">Keine Immobilie zugeordnet.</div>';if(tab==='overview')return `<div class="overview-grid"><article class="cockpit-card"><span class="kicker">KUNDE</span><h3>${esc([d.user.first_name,d.user.last_name].filter(Boolean).join(' ')||d.user.name)}</h3>${field('E-Mail',d.user.email)}${field('Telefon',d.user.phone_number)}${field('Post- und Rechnungsadresse',[d.user.address,d.user.postal_code,d.user.city].filter(Boolean).join(', '))}</article><article class="cockpit-card"><span class="kicker">IMMOBILIE</span><h3>${esc([[p.streetName||p.street_name,p.house_number||p.houseNumber||p.address].filter(Boolean).join(' '),p.zip_code||p.postal_code,p.city].filter(Boolean).join(', ')||'Objekt')}</h3>${field('Objekttyp',p.property_type)}${field('Baujahr',p.year_of_construction)}${field('Wohnfläche',p.living_space)}${field('Grundstück',p.property_area)}</article><article class="cockpit-card"><span class="kicker">AKTENSTATUS</span><h3>${rows('property_files').length} Dokumente</h3>${field('Technische Gewerke',['roof_data','heating_data','windows_data','facade_data','electrical1_data','sanitary_data','photvoltaik_data'].filter(x=>rows(x).length).length)}${field('Offene Erinnerungen',rows('reminders').length)}${field('Verträge',rows('financings').length+rows('insurances').length)}</article></div>`;if(tab==='property')return `<article class="cockpit-card"><div class="card-head"><div><h3>Immobilienstammdaten</h3><span class="muted">Objekt ${esc(p.id)}</span></div><span class="status ${p.duplicateAddress&&!p.addressVerification?.verified?'high':''}">${p.addressVerification?.verified?'Grundbuch fachlich verifiziert':p.duplicateAddress?'Kritische Adressdublette':'Adresse nicht verifiziert'}</span></div>${grid(p)}${p.addressVerification?.verified?`<div class="source-note"><b>Eigentümer, Adresse und Flurstück fachlich verifiziert</b> · ${new Date(p.addressVerification.verifiedAt).toLocaleString('de-DE')}<br><a class="outline" href="/api/production/properties/${p.id}/land-register" target="_blank" rel="noopener">Grundbuch einsehen</a></div>`:''}${['super_admin','admin_light'].includes(state.user?.role)?`<button class="primary" id="verify-property-address">${p.addressVerification?.verified?'Verifizierung aktualisieren':'Adresse eindeutig verifizieren'}</button>`:''}</article>`;if(tab==='trades'){const trades=[['Dach','roof_data'],['Heizung','heating_data'],['Fenster & Türen','windows_data'],['Fassade','facade_data'],['Elektro','electrical1_data'],['Sanitär','sanitary_data'],['Photovoltaik','photvoltaik_data'],['Räume','room_data'],['Lüftung','ventilation_data'],['Kamin','fireplace_data'],['Küche','kitchen_data']];return `<div class="trade-grid">${trades.map(([name,key])=>`<details class="cockpit-card" ${rows(key).length?'':'data-empty'}><summary><span>${name}</span><span class="status">${rows(key).length||'–'}</span></summary>${rows(key).length?rows(key).map(grid).join(''):'<p class="muted">Noch keine Angaben erfasst.</p>'}</details>`).join('')}</div>`}if(tab==='service')return `<div class="stack">${block('Prüfungen & Wartungen',rows('inspections'))}${block('Erinnerungen',rows('reminders'))}${block('Kommunikation',rows('communications'))}</div>`;if(tab==='documents'){const docs=rows('property_files');return `<article class="cockpit-card"><div class="card-head"><h3>Dokumentenarchiv</h3><span class="status">${docs.filter(x=>x.fileAvailable).length} verfügbar</span></div><div class="document-grid">${docs.map(x=>`<div class="document-row"><span class="document-icon">PDF</span><div><b>${esc(x.screen_name||x.pdf_certificate||'Objektdokument')}</b><small>${x.fileAvailable?'Sicher im Archiv verfügbar':'Datei im Export nicht enthalten'}</small></div>${x.fileAvailable?`<a class="outline" href="${esc(x.viewUrl)}" target="_blank" rel="noopener">Ansehen</a>`:'<span class="muted">Nicht verfügbar</span>'}</div>`).join('')||'<p class="muted">Keine Dokumente hinterlegt.</p>'}</div></article>`}return `<div class="stack">${block('Finanzierungen',rows('financings'))}${block('Versicherungen',rows('insurances'))}${block('Verbräuche & Versorger',rows('consumptions'))}</div>`}
const renderCockpitBase=renderCockpit;renderCockpit=()=>{renderCockpitBase();if(state.user?.role!=='super_admin'||!state.cockpit?.user)return;const hero=$('.cockpit-hero');hero.insertAdjacentHTML('beforeend',`<div class="customer-admin-actions"><button class="outline" id="edit-production-customer">Kundendaten ändern</button><button class="danger-button" id="delete-production-customer">Kunde löschen</button>${state.cockpit.sourceSyncStatus==='pending'?'<span class="status invited">Synchronisation ausstehend</span>':''}</div>`);$('#edit-production-customer').onclick=editProductionCustomer;$('#delete-production-customer').onclick=deleteProductionCustomer};
function editProductionCustomer(){const u=state.cockpit.user;modal('Kundenstammdaten bearbeiten',`<form id="production-customer-edit"><div class="form-grid"><label>Vorname<input name="first_name" value="${esc(u.first_name||'')}"></label><label>Nachname<input name="last_name" value="${esc(u.last_name||'')}"></label></div><label>E-Mail<input type="email" name="email" value="${esc(u.email||'')}"></label><label>Telefon<input name="phone_number" value="${esc(u.phone_number||'')}"></label><label>Adresse<input name="address" value="${esc(u.address||'')}"></label><div class="form-grid"><label>Postleitzahl<input name="postal_code" maxlength="5" value="${esc(u.postal_code||'')}"></label><label>Ort<input name="city" value="${esc(u.city||'')}"></label></div><label>Status<select name="status"><option value="active" ${u.status==='active'?'selected':''}>Aktiv</option><option value="paused" ${u.status==='paused'?'selected':''}>Pausiert</option><option value="blocked" ${u.status==='blocked'?'selected':''}>Gesperrt</option></select></label><button class="primary">Änderungen speichern</button></form>`);$('#production-customer-edit').onsubmit=async e=>{e.preventDefault();await api(`/api/production/customers/${encodeURIComponent(u.id)}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Kundendaten geändert und protokolliert');await renderProductionCustomer(u.id)}}
async function deleteProductionCustomer(){const u=state.cockpit.user,name=[u.first_name,u.last_name].filter(Boolean).join(' ')||u.name||u.email;if(!confirm(`Kunde ${name} wirklich löschen? Die Akte wird im Partner OS sofort entfernt und zur Löschung in der Quell-App vorgemerkt.`))return;await api(`/api/production/customers/${encodeURIComponent(u.id)}`,{method:'DELETE'});state.cockpit=null;toast('Kunde gelöscht und Quellsynchronisation vorgemerkt');render('production')}
function setup(user,csrf,supportView=null){state.user=user;state.csrf=csrf;state.supportView=supportView;window.ehvPortalContext={user,csrf,supportView};$('#login').hidden=true;$('#app').hidden=false;$('#user-name').textContent=user.name;$('#user-role').textContent=supportView?`${labels[user.role]} · Support-Sicht`:labels[user.role];$('#avatar').textContent=user.name.split(' ').map(x=>x[0]).join('').slice(0,2);const banner=$('#support-view-banner');banner.hidden=!supportView;banner.innerHTML=supportView?`<div><b>Support-Sicht: ${esc(user.name)}</b><span>Schreibgeschützte Partneransicht · Administrator: ${esc(supportView.actor.name)}</span></div><button class="outline" id="support-view-stop">Support-Sicht beenden</button>`:'';if(supportView)$('#support-view-stop').onclick=async()=>{const d=await api('/api/support-view/stop',{method:'POST',body:'{}'});setup(d.user,d.csrf,d.supportView)};$('#quick-create').hidden=Boolean(supportView)||['support_staff','partner_basic','referral_partner'].includes(user.role);const roleMenus={super_admin:['dashboard','production','opportunities','partners'],admin_light:['dashboard','production','partners','opportunities'],support_staff:['dashboard','production','partners'],partner_manager:['dashboard','partners','cases'],crafts_partner:['dashboard','workbench','opportunities','cases'],broker_partner:['dashboard','brokerCustomers','opportunities'],partner_basic:['dashboard'],referral_partner:['dashboard']},allowedIds=roleMenus[user.role]||['dashboard'],allowed=navs.filter(([id])=>allowedIds.includes(id));$('#nav').innerHTML=allowed.map(([id,ic,n])=>`<button data-page="${id==='dashboard'?(user.role==='crafts_partner'?'partnerDashboard':user.role==='broker_partner'?'brokerDashboard':user.role==='admin_light'?'adminLightDashboard':'dashboard'):id}"><span>${navIcons[id]||ic}</span>${n}</button>`).join('');$('#nav').onclick=e=>{const b=e.target.closest('button');if(b?.dataset.page){render(b.dataset.page);closeNav()}};buildUserMenu();if(['partner_basic','referral_partner'].includes(user.role)){renderBasicDashboard();return}render(user.role==='crafts_partner'?'partnerDashboard':user.role==='broker_partner'?'brokerDashboard':user.role==='admin_light'?'adminLightDashboard':'dashboard')}
async function render(page){if(page==='sales')page='brokerCustomers';state.page=page;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));const pageName=page==='partnerDashboard'?'Dashboard':(navs.find(x=>x[0]===page)||[])[2]||'';$('#section-label').textContent=pageName;$('#page-title').textContent=page==='dashboard'||page==='partnerDashboard'?`Guten Morgen, ${state.user.name.split(' ')[0]}`:pageName;$('#content').innerHTML='<div class="page muted">Daten werden geladen …</div>';try{await pages[page]();if(page==='workbench'&&['crafts_partner','broker_partner'].includes(state.user.role))await mountReferralActions();if(page==='dashboard'&&state.user.role==='super_admin'){await showCriticalPartnerPanel();await enhanceDashboardMap();await enhanceAdminInsights()}translateUi($('#content'))}catch(e){$('#content').innerHTML=`<div class="page"><div class="card error">${esc(e.message)}</div></div>`}}
const assignmentPage=async()=>{const d=await api('/api/assignments');$('#content').innerHTML=`<div class="page"><div class="toolbar"><div><span class="kicker">ZUGRIFFSSTEUERUNG</span><h3>Explizite Objektzuweisungen</h3></div><button class="primary" id="new-assignment">+ Zuweisung</button></div><div class="card table-wrap"><table><thead><tr><th>Partner</th><th>Objekt</th><th>Gewerk</th><th>Zeitraum</th><th>Regionalregel</th></tr></thead><tbody>${d.assignments.map(a=>`<tr><td><b>${esc(d.partners.find(p=>p.id===a.partnerId)?.company||a.partnerId)}</b></td><td>${esc(d.properties.find(p=>p.id===a.propertyId)?.ehvId||a.propertyId)}</td><td>${esc(d.trades.find(t=>t.id===a.tradeId)?.name||'Alle')}</td><td>${esc(a.accessStart)} – ${esc(a.accessEnd||'unbefristet')}</td><td><span class="status ${a.overrideRegion?'invited':''}">${a.overrideRegion?'Manuelle Ausnahme':'Lizenzgebiet'}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Noch keine Zuweisungen.</td></tr>'}</tbody></table></div></div>`;$('#new-assignment').onclick=()=>modal('Objekt sicher zuweisen',`<form id="assignment-form"><label>Partner<select name="partnerId">${d.partners.map(p=>`<option value="${p.id}">${esc(p.company)}</option>`)}</select></label><label>Objekt<select name="propertyId">${d.properties.map(p=>`<option value="${p.id}">${p.ehvId} · ${esc(p.address)}</option>`)}</select></label><div class="form-grid"><label>Gewerk<select name="tradeId">${d.trades.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`)}</select></label><label>Freigabe ab<input type="date" name="accessStart" value="${new Date().toISOString().slice(0,10)}"></label></div><label><span><input type="checkbox" name="overrideRegion" style="width:auto"> Objekt außerhalb des Lizenzgebiets ausdrücklich freigeben</span></label><button class="primary wide-action">Zuweisung protokolliert speichern</button></form>`);setTimeout(()=>$('#assignment-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.overrideRegion=e.target.overrideRegion.checked;await api('/api/assignments',{method:'POST',body:JSON.stringify(f)});closeModal();toast('Zuweisung gespeichert und protokolliert');render('assignments')},0)};
const partnerAccountsPage=async()=>{const d=await api('/api/partners'),tradeName=id=>d.trades.find(t=>t.id===id)?.name||id;$('#content').innerHTML=`<div class="page"><div class="toolbar"><div><span class="kicker">ORGANISATIONEN & GEWERKEKONTEN</span><h3>Ein sicherer Zugang pro Gewerk</h3><p class="muted">Auch bei Großpartnern erhält jedes Gewerk einen eigenen Account, eigene PLZ-Lizenzen und eine getrennte Rechtebasis.</p></div><button class="primary" id="new-trade-account">+ Gewerkekonto</button></div><div class="card table-wrap"><table><thead><tr><th>Organisation / Zugang</th><th>Gewerk</th><th>Lizenzgebiet</th><th>Onboarding</th><th>Status</th></tr></thead><tbody id="rows">${d.partners.map(p=>`<tr><td><b>${esc(d.organizations.find(o=>o.id===p.organizationId)?.name||p.company)}</b><br><small>${esc(p.contact)} · ${esc(p.email)}</small></td><td><span class="status">${esc(tradeName(p.primaryTradeId))}</span></td><td>${p.postalCodes.map(esc).join(', ')||'–'}</td><td>${p.onboarding}%<div class="progress"><i style="width:${p.onboarding}%"></i></div></td><td><span class="status ${p.status}">${p.status==='active'?'Aktiv':'Eingeladen'}</span></td></tr>`).join('')}</tbody></table></div></div>`;$('#new-trade-account').onclick=()=>{modal('Neues Gewerkekonto',`<form id="trade-account-form"><div class="source-note">Eine Organisation kann mehrere Gewerke führen. Für Nachvollziehbarkeit und Datenschutz wird trotzdem je Gewerk eine eigene, unveränderbare Login-E-Mail benötigt.</div><div class="form-grid"><label>Organisation / Firma<input name="company" list="org-list" required><datalist id="org-list">${d.organizations.map(o=>`<option value="${esc(o.name)}">`)}</datalist></label><label>Ansprechperson<input name="contact" required></label></div><label>Login-E-Mail des Gewerkekontos<input name="email" type="email" required></label><label>Genau ein Gewerk<select id="account-trade" name="tradeId" required><option value="">Bitte auswählen</option>${d.trades.map(t=>`<option value="${t.id}">${esc(t.name)} · ${t.tier==='premium'?'Premium':'Standard'}</option>`)}</select></label><label>Lizenz-PLZ suchen<input id="postal-search" placeholder="PLZ, Ort oder Bundesland" autocomplete="off"></label><div id="postal-results" class="postal-results muted">Bitte zuerst ein Gewerk wählen.</div><div><b>Ausgewählte Lizenzgebiete</b><div id="postal-selected" class="chip-list"></div></div><button class="primary wide-action">Einladung & Lizenz vorbereiten</button></form>`);const selected=new Map(),trade=$('#account-trade'),search=$('#postal-search'),results=$('#postal-results'),chips=$('#postal-selected');const draw=()=>{chips.innerHTML=[...selected.values()].map(x=>`<button type="button" class="status" data-remove="${x.postalCode}">${x.postalCode} ${esc(x.city)} ×</button>`).join('')||'<span class="muted">Noch keine PLZ ausgewählt</span>';chips.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{selected.delete(b.dataset.remove);draw()})};
const load=async()=>{if(!trade.value){results.textContent='Bitte zuerst ein Gewerk wählen.';return}const r=await api(`/api/postal-codes?tradeId=${encodeURIComponent(trade.value)}&q=${encodeURIComponent(search.value)}`);results.innerHTML=r.entries.map(x=>`<button type="button" data-postal="${x.postalCode}" ${x.occupied?'disabled':''}><b>${x.postalCode} ${esc(x.city)}</b><small>${esc(x.state)} · ${x.occupied?'belegt durch '+esc(x.occupiedBy.join(', ')):'frei'}</small></button>`).join('')||'<span class="muted">Keine passende PLZ gefunden.</span>';results.querySelectorAll('[data-postal]:not(:disabled)').forEach(b=>b.onclick=()=>{const x=r.entries.find(y=>y.postalCode===b.dataset.postal);selected.set(x.postalCode,x);draw()})};trade.onchange=load;search.oninput=load;draw();$('#trade-account-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await api('/api/partners',{method:'POST',body:JSON.stringify({company:f.get('company'),contact:f.get('contact'),email:f.get('email'),tradeIds:[f.get('tradeId')],postalCodes:[...selected.keys()]})});closeModal();toast('Getrenntes Gewerkekonto angelegt');render('partners')}}};
async function openTradeAccountModal(){const d=await api('/api/partners');modal('Neues Gewerkekonto anlegen',`<form id="new-trade-account-form"><div class="source-note">Pro Zugang wird genau ein Gewerk vergeben. Ein Unternehmen mit mehreren Gewerken erhält entsprechend mehrere getrennte Zugänge.</div><div class="form-grid"><label>Organisation / Firma<input name="company" list="new-org-list" required><datalist id="new-org-list">${d.organizations.map(o=>`<option value="${esc(o.name)}">`)}</datalist></label><label>Ansprechperson<input name="contact" required></label></div><label>Unveränderbare Login-E-Mail<input name="email" type="email" required></label><label>Gewerk<select id="new-account-trade" name="tradeId" required><option value="">Genau ein Gewerk auswählen</option>${d.trades.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`)}</select></label><label>Lizenzgebiet suchen<input id="new-postal-search" placeholder="PLZ, Ort oder Bundesland" autocomplete="off"></label><div id="new-postal-results" class="postal-results muted">Bitte zuerst ein Gewerk auswählen.</div><div><b>Ausgewählte Postleitzahlen</b><div id="new-postal-selected" class="chip-list"></div></div><button class="primary wide-action">Gewerkekonto anlegen</button></form>`);const selected=new Map(),trade=$('#new-account-trade'),search=$('#new-postal-search'),results=$('#new-postal-results'),chips=$('#new-postal-selected');const draw=()=>{chips.innerHTML=[...selected.values()].map(x=>`<button type="button" class="status" data-remove="${x.postalCode}">${x.postalCode} ${esc(x.city)} ×</button>`).join('')||'<span class="muted">Noch keine Postleitzahl ausgewählt.</span>';chips.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{selected.delete(b.dataset.remove);draw()})};
const load=async()=>{if(!trade.value){results.textContent='Bitte zuerst ein Gewerk auswählen.';return}const r=await api(`/api/postal-codes?tradeId=${encodeURIComponent(trade.value)}&q=${encodeURIComponent(search.value)}`);results.innerHTML=r.entries.map(x=>`<button type="button" data-postal="${x.postalCode}" ${x.occupied?'disabled':''}><b>${x.postalCode} ${esc(x.city)}</b><small>${esc(x.state)} · ${x.occupied?'bereits belegt':'verfügbar'}</small></button>`).join('')||'<span class="muted">Keine passende Postleitzahl gefunden.</span>';results.querySelectorAll('[data-postal]:not(:disabled)').forEach(b=>b.onclick=()=>{const x=r.entries.find(y=>y.postalCode===b.dataset.postal);selected.set(x.postalCode,x);draw()})};trade.onchange=()=>{selected.clear();draw();load()};search.oninput=load;draw();$('#new-trade-account-form').onsubmit=async e=>{e.preventDefault();if(!selected.size)return toast('Bitte mindestens eine verfügbare Postleitzahl auswählen');const f=new FormData(e.target);await api('/api/partners',{method:'POST',body:JSON.stringify({company:f.get('company'),contact:f.get('contact'),email:f.get('email'),tradeIds:[f.get('tradeId')],postalCodes:[...selected.keys()]})});closeModal();toast('Gewerkekonto angelegt und Einladung vorbereitet');render('partners')}}
const accessPage=async()=>{const d=await api('/api/admin/users');$('#content').innerHTML=`<div class="page"><div class="toolbar"><div><span class="kicker">ZUGANGSSICHERHEIT</span><h3>Benutzerzugänge</h3><p class="muted">Login-E-Mails sind unveränderbare Identitäten. Rollen- oder E-Mail-Wechsel erfolgen nicht stillschweigend, sondern über einen kontrollierten Migrationsprozess.</p></div></div><div class="card table-wrap"><table><thead><tr><th>Benutzer</th><th>Login-E-Mail</th><th>Rolle</th><th>Zustand</th></tr></thead><tbody>${d.users.map(u=>`<tr><td><b>${esc(u.name)}</b></td><td>${esc(u.email)} <span class="status">gesperrt</span></td><td>${esc(labels[u.role]||u.role)}</td><td><span class="status ${u.active?'active':'invited'}">${u.active?'Aktiv':'Deaktiviert'}</span></td></tr>`).join('')}</tbody></table></div><div class="card table-wrap" style="margin-top:18px"><div class="card-head"><h3>Eingeladene Partnerzugänge</h3></div><table><thead><tr><th>Firma</th><th>Login-E-Mail</th><th>Gewerk</th><th>Status</th></tr></thead><tbody>${d.partners.map(p=>`<tr><td>${esc(p.company)}</td><td>${esc(p.email)}</td><td>${esc(p.tradeId)}</td><td>${esc(p.status)}</td></tr>`).join('')}</tbody></table></div></div>`};
const auditPage=async()=>{const d=await api('/api/audit'),entities={user:'Benutzer',partner:'Partner',assignment:'Objektzuweisung',equipment:'Anlage',service_case:'Servicefall',role_profile:'Rollenprofil',property_file:'Dokument',production:'Produktivdaten',campaign:'Kampagne',permission:'Berechtigung'};$('#content').innerHTML=`<div class="page"><div class="card"><div class="card-head"><div><span class="kicker">ÄNDERUNGSPROTOKOLL</span><h3>Nachvollziehbare Systemereignisse</h3></div><span class="status">Nachträglich nicht veränderbar</span></div><table><thead><tr><th>Zeitpunkt</th><th>Ausgeführt von</th><th>Vorgang</th><th>Bereich</th><th>Zusatzangaben</th></tr></thead><tbody>${d.audit.map(a=>`<tr><td>${new Date(a.at).toLocaleString('de-DE')}</td><td>${esc(a.userId)}</td><td><b>${esc(auditActionLabel(a.action))}</b></td><td>${esc(entities[a.entity]||a.entity)} · ${esc(a.entityId)}</td><td class="audit-detail">${esc(Object.entries(a.details||{}).map(([k,v])=>`${k}: ${Array.isArray(v)?v.join(', '):v}`).join(' · ')||'Keine')}</td></tr>`).join('')}</tbody></table></div></div>`};
const partnerManagementPage=async()=>{const [d,q]=await Promise.all([api('/api/partners'),api('/api/partner-performance')]),scores=new Map(q.scores.map(x=>[x.partnerId,x]));$('#content').innerHTML=`<div class="page"><div class="toolbar"><div><span class="kicker">KOOPERATIONSPARTNER</span><h3>Partner, Lizenzen und Qualität</h3><p class="muted">Jede Zeile öffnet die vollständige Partnerakte.</p></div><button class="primary" id="create-partner">+ Gewerkekonto</button></div><div class="card table-wrap"><div class="card-head"><input id="partner-search" placeholder="Firma, Kontakt, E-Mail, Gewerk oder PLZ …"></div><table><thead><tr><th>Partner</th><th>Gewerk</th><th>Lizenzgebiet</th><th>Scoring</th><th>Status</th><th></th></tr></thead><tbody id="partner-rows">${d.partners.map(p=>{const s=scores.get(p.id);return `<tr><td><b>${esc(p.company)}</b><br><small>${esc(p.contact)} · ${esc(p.email)}</small></td><td>${esc(d.trades.find(t=>t.id===p.primaryTradeId)?.name||p.primaryTradeId)}</td><td>${p.postalCodes.map(esc).join(', ')}</td><td><b class="${s?.critical?'danger':''}">${s?.score??0}%</b><br><small>${s?.confidence==='sufficient'?'belastbar':'vorläufig'}</small></td><td><span class="status ${p.status}">${p.status==='active'?'Aktiv':p.status==='paused'?'Pausiert':p.status==='archived'?'Archiviert':'Eingeladen'}</span></td>
<td><button class="outline partner-record" data-id="${p.id}">Partnerakte</button> <button class="primary partner-360" data-id="${p.id}" ${p.status==='active'?'':'disabled'}>360° Ansicht</button></td></tr>`}).join('')}</tbody></table></div></div>`;$('#partner-search').oninput=e=>document.querySelectorAll('#partner-rows tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()));document.querySelectorAll('.partner-record').forEach(b=>b.onclick=()=>openPartnerRecord(b.dataset.id));document.querySelectorAll('.partner-360').forEach(b=>b.onclick=()=>startPartnerSupportView(b.dataset.id));$('#create-partner').onclick=()=>{toast('Neue Gewerkekonten werden über die Zugangsverwaltung konfiguriert');render('roles')}};
async function openPartnerRecord(id){const d=await api(`/api/partners/${id}`),p=d.partner,s=d.score;$('#section-label').textContent='PARTNERAKTE';$('#page-title').textContent=p.company;$('#content').innerHTML=`<div class="page"><button class="link partner-back">← Alle Partner</button><section class="equipment-hero"><div><span class="kicker">${esc(d.trade?.name||p.primaryTradeId)} · ${esc(p.id)}</span><h1>${esc(p.company)}</h1><p>${esc(p.contact)} · ${esc(p.email)}</p></div><span class="status ${p.status}">${esc(p.status)}</span></section><div class="kpis">${[['Partner-Score',s.score+'%'],['Ø Reaktion',s.metrics.avgResponseHours===null?'–':s.metrics.avgResponseHours+' Std.'],['Annahme',s.metrics.acceptance+'%'],['Dokumentation',s.metrics.documentation+'%']].map(x=>`<div class="card kpi"><span class="muted">${x[0]}</span><div class="value">${x[1]}</div></div>`).join('')}</div><div class="grid-2"><article class="cockpit-card"><h3>Partnerdaten bearbeiten</h3><form id="partner-edit"><label>Firma<input name="company" value="${esc(p.company)}"></label><label>Ansprechperson<input name="contact" value="${esc(p.contact)}"></label><label>Login-E-Mail<input value="${esc(p.email)}" readonly></label><label>Status<select name="status">${[['active','Aktiv'],['paused','Pausiert'],['invited','Eingeladen'],['archived','Archiviert']].map(([v,l])=>`<option value="${v}" ${p.status===v?'selected':''}>${l}</option>`)}</select></label><button class="primary">Änderungen speichern</button></form></article><article class="cockpit-card"><h3>Lizenz & Bestand</h3><p><b>Organisation</b><br>${esc(d.organization?.name||p.company)}</p><p><b>Gewerk</b><br>${esc(d.trade?.name||p.primaryTradeId)}</p><p><b>Lizenz-PLZ</b><br>${p.postalCodes.map(esc).join(', ')}</p><p><b>Zugeordnete Objekte</b><br>${d.properties.length}</p><button class="danger-button" id="delete-partner">Partner endgültig löschen</button></article></div><article class="card table-wrap" style="margin-top:18px"><div class="card-head"><h3>Zugeordnete Immobilien</h3></div><table><thead><tr><th>Objekt-ID</th><th>Adresse</th><th>Zugriffsgrund</th></tr></thead><tbody>${d.properties.map(x=>`<tr><td>${esc(x.ehvId)}</td><td>${esc(x.address)}, ${esc(x.postalCode)} ${esc(x.city)}</td><td>${d.assignments.find(a=>a.propertyId===x.id)?.overrideRegion?'Manuelle Ausnahme':'Lizenzgebiet'}</td></tr>`).join('')||'<tr><td colspan="3">Keine Objekte zugeordnet.</td></tr>'}</tbody></table></article></div>`;$('.partner-back').onclick=()=>render('partners');$('#partner-edit').onsubmit=async e=>{e.preventDefault();await api(`/api/partners/${id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast('Partnerdaten gespeichert');openPartnerRecord(id)};$('#delete-partner').onclick=async()=>{if(!confirm(`Partner ${p.company} wirklich endgültig löschen? Zugeordnete Freigaben werden entfernt.`))return;await api(`/api/partners/${id}`,{method:'DELETE'});toast('Partner gelöscht und protokolliert');render('partners')}}
const adminDashboardPage=async()=>{if(state.user.role!=='super_admin')return pages.dashboardLegacy();const [base,analytics,risks,quality]=await Promise.all([api('/api/dashboard'),api('/api/analytics/overview').catch(()=>null),api('/api/portfolio/risks').catch(()=>null),api('/api/partner-performance')]),regions=analytics?.regions||{},points=[['SH',145,45,'Schleswig-Holstein'],['HH',150,77,'Hamburg'],['NI',125,115,'Niedersachsen'],['HB',99,103,'Bremen'],['MV',205,82,'Mecklenburg-Vorpommern'],['BE',224,126,'Berlin'],['BB',230,140,'Brandenburg'],['ST',178,150,'Sachsen-Anhalt'],['NW',74,158,'Nordrhein-Westfalen'],['HE',115,205,'Hessen'],['TH',162,195,'Thüringen'],['SN',210,195,'Sachsen'],['RP',78,220,'Rheinland-Pfalz'],['SL',68,252,'Saarland'],['BW',110,275,'Baden-Württemberg'],['BY',174,270,'Bayern']];$('#content').innerHTML=`<div class="page admin-command"><section class="admin-welcome"><div><span class="kicker">ADMIN PLUS · LIVE COCKPIT</span><h1>Guten Morgen, ${esc(state.user.name.split(' ')[0])}.</h1><p>Steuern Sie Kundenbestand, Partnerqualität und operative Risiken aus einer zentralen Übersicht.</p></div><div class="admin-actions"><button class="primary" data-go="production">Kundenakte öffnen</button><button class="outline" data-go="partners">Partner verwalten</button></div></section><section class="kpis admin-kpis">${[['Aktive Kunden',analytics?.summary.registered??base.kpis.properties,'◉'],['Immobilien',base.kpis.properties,'⌂'],['Aktive Partner',base.kpis.partners,'♙'],['Offene Servicefälle',base.kpis.openCases,'◇'],['Kritische Partner',quality.summary.critical,'!'],['Kritische Anlagen',risks?.summary.critical??0,'△']].map(([l,v,i])=>`<button class="card kpi dashboard-kpi"><span class="muted">${l}</span><div class="value">${v}</div><b class="bubble">${i}</b></button>`).join('')}</section><div class="admin-dashboard-grid"><article class="card germany-panel"><div class="card-head"><div><span class="kicker">NUTZUNG & REGIONEN</span><h3>Kundenverteilung Deutschland</h3></div><button class="link" data-go="analytics">Detailanalyse →</button></div><svg class="germany-svg" viewBox="0 0 300 340" role="img" aria-label="Deutschlandkarte mit Registrierungen"><path d="M124 20 L164 26 181 46 213 49 226 78 252 93 239 123 257 147 237 173 245 204 216 221 218 257 194 273 187 316 153 326 133 302 99 303 88 276 58 259 71 226 45 204 59 173 42 143 67 119 67 83 98 71 102 39 Z"/><g>${points.map(([short,x,y,name])=>{const n=regions[name]?.registered||0;return `<g class="map-point"><circle cx="${x}" cy="${y}" r="${n?14:10}"/><text x="${x}" y="${y-1}">${short}</text><text class="map-count" x="${x}" y="${y+10}">${n}</text><title>${name}: ${n} Kunden</title></g>`}).join('')}</g></svg><p class="muted map-caption">Zahl je Bundesland · Klick auf „Detailanalyse“ öffnet Nutzung, Aktivierungsfunnel und Datenqualität.</p></article><div class="dashboard-modules"><details class="card dashboard-module" open><summary><div><span class="kicker">BESTAND & RISIKEN</span><h3>${risks?.summary.critical??0} kritische · ${risks?.summary.review??0} zu prüfen</h3></div><span>⌄</span></summary><div class="module-body"><div class="metric-strip"><div><b>${risks?.summary.equipment??0}</b><small>Anlagen</small></div><div><b>${risks?.summary.withoutDocuments??0}</b><small>ohne Dokumente</small></div></div><button class="outline" data-go="portfolio">Bestandsanalyse öffnen</button></div></details><details class="card dashboard-module" open><summary><div><span class="kicker">PARTNERQUALITÄT</span><h3>Ø ${quality.summary.average}% · ${quality.summary.critical} kritisch</h3></div><span>⌄</span></summary><div class="module-body">${quality.scores.slice(0,4).map(s=>`<div class="quality-line"><span>${esc(s.partner)}</span><b class="${s.critical?'danger':''}">${s.score}%</b></div>`).join('')}<button class="outline" data-go="performance">Gesamtes Scoring öffnen</button></div></details><details class="card dashboard-module"><summary><div><span class="kicker">NUTZUNG</span><h3>${analytics?.summary.active30??0} aktive Nutzer · Ø ${analytics?.summary.averageCompleteness??0}% Datenqualität</h3></div><span>⌄</span></summary><div class="module-body"><p>${analytics?.summary.measuredUsers??0} Nutzer sind telemetrisch messbar. ${analytics?.summary.registered30??0} neue Registrierungen in 30 Tagen.</p><button class="outline" data-go="analytics">Nutzungsanalyse öffnen</button></div></details></div></div><section class="card operational-list"><div class="card-head"><div><span class="kicker">OPERATIVER POSTEINGANG</span><h3>Aktuelle Servicefälle</h3></div><button class="link" data-go="cases">Alle Servicefälle →</button></div>${caseTable(base.recentCases,base.properties)}</section></div>`;bindGo()};
const partnerDashboardPage=async()=>{const [d,c]=await Promise.all([api('/api/partner/workbench'),api('/api/cases')]),open=c.cases.filter(x=>x.status!=='done'),urgent=open.filter(x=>x.priority==='high'),documents=d.serviceRecords.reduce((n,r)=>n+(r.documents?.length||0),0);$('#content').innerHTML=`<div class="page partner-dashboard"><section class="hero"><div><span class="kicker">${esc(d.partner.tradeName)} · PARTNER-DASHBOARD</span><h1>Guten Morgen, ${esc(state.user.name.split(' ')[0])}.</h1><p>Kunden, Aufträge und Anlagenzustände Ihres freigegebenen Gebiets auf einen Blick.</p></div><button class="primary" data-go="workbench">Alle Kunden öffnen →</button></section><section class="kpis">${[['Zugeordnete Kunden',d.summary.customers],['Offene Aufträge',open.length],['Dringende Aufträge',urgent.length],['Wartung erforderlich',d.summary.due],['Kritische Anlagen',d.summary.critical],['Service-Dokumente',documents]].map(([l,v])=>`<div class="card kpi"><span class="muted">${l}</span><div class="value">${v}</div></div>`).join('')}</section><div class="grid-2 partner-dashboard-grid"><article class="card"><div class="card-head"><div><span class="kicker">MEINE KUNDEN</span><h3>Direkter Zugang zur Kundenakte</h3></div><button class="link" data-go="workbench">Alle anzeigen</button></div>${d.customers.flatMap(customer=>customer.properties.map(property=>{const equipment=property.equipment[0];return `<div class="partner-customer-card"><div><b>${esc(customer.name)}</b><small>${esc(property.ehvId)} · ${esc(property.address)}, ${esc(property.postalCode)} ${esc(property.city)}</small><span>${equipment?`${esc(equipment.label)} · Anlagenzustand ${equipment.health.score}/100`:`${esc(d.partner.tradeName)} noch nicht erfasst`}</span></div><button class="outline dashboard-customer" data-property="${property.id}" data-equipment="${equipment?.id||''}">Kundenakte öffnen</button></div>`})).join('')||'<p class="muted">Aktuell sind keine Kunden zugeordnet.</p>'}</article><article class="card"><div class="card-head"><div><span class="kicker">AUFTRÄGE</span><h3>Offene Servicefälle</h3></div><button class="link" data-go="cases">Alle öffnen</button></div>${open.slice(0,6).map(item=>{const property=c.properties.find(p=>p.id===item.propertyId);return `<div class="partner-customer-card"><div><b>${esc(item.title)}</b><small>${esc(property?.ehvId||item.propertyId)} · ${esc(property?.address||'')}</small><span>${esc(item.category)} · ${item.priority==='high'?'Hohe Priorität':'Normale Priorität'}</span></div><span class="status ${item.priority==='high'?'high':''}">${statusLabel(item.status)}</span></div>`}).join('')||'<p class="muted">Keine offenen Servicefälle.</p>'}</article></div></div>`;bindGo();document.querySelectorAll('.dashboard-customer').forEach(b=>b.onclick=()=>b.dataset.equipment?openPartnerEquipment(b.dataset.equipment,'overview'):openPartnerProperty(b.dataset.property))};
const opportunityPage=async()=>{const d=await api('/api/opportunity-engine');if(d.scope==='partner_aggregate'){const definition=id=>d.definitions.find(x=>x.id===id),event=id=>d.events.find(x=>x.id===id);$('#content').innerHTML=`<div class="page"><section class="hero"><div><span class="kicker">ANLÄSSE · DATENMINIMIERT</span><h1>Relevante Servicechancen in Ihrem Gewerk.</h1><p>Sie sehen zunächst ausschließlich aggregierte Bedarfe. Kundendaten werden erst nach Kundenreaktion und konkreter Objektfreigabe sichtbar.</p></div></section><div class="kpis">${[['Aktive Anlässe',d.kpis.opportunities],['Potenziell relevante Objekte',d.kpis.properties],['Hohe Priorität',d.kpis.highPriority],['Abgeschlossen',d.kpis.completed]].map(([l,v])=>`<div class="card kpi"><span class="muted">${l}</span><div class="value">${v}</div></div>`).join('')}</div><div class="opportunity-list">${d.opportunities.map(o=>{const def=definition(o.triggerDefinitionId),ev=event(o.triggerEventId);return `<article class="cockpit-card opportunity-card"><div class="card-head"><div><span class="kicker">${esc(def?.category||'Anlass')}</span><h3>${esc(def?.name||'Opportunity')}</h3></div><span class="status ${o.status==='completed'?'':'invited'}">${esc(statusLabel(o.status))}</span></div><div class="metric-strip"><div><b>${o.propertyCount}</b><small>Betroffene Objekte</small></div><div><b>${o.highPriorityCount}</b><small>Hohe Priorität</small></div><div><b>${ev?.severity??'–'}</b><small>Schwere</small></div></div><p>${esc(def?.description||'')}</p><p class="muted">Region: ${esc(ev?.region||ev?.state||'–')} · Equipment: ${(def?.relevantEquipmentTypes||[]).map(esc).join(', ')} · Empfehlung: ${esc(def?.partnerActionType||'Prüfung')}</p>${o.status==='assigned'?`<button class="primary opportunity-complete" data-id="${o.id}">Freigegebenen Service abschließen</button>`:'<div class="source-note">Noch keine konkrete Kundenfreigabe – keine personenbezogenen Daten sichtbar.</div>'}</article>`}).join('')||'<div class="card empty">Aktuell liegen keine Partner-Opportunities vor.</div>'}</div></div>`;document.querySelectorAll('.opportunity-complete').forEach(b=>b.onclick=()=>{modal('Serviceergebnis dokumentieren',`<form id="opportunity-complete-form"><label>Ergebnis<select name="outcome"><option value="ok">In Ordnung</option><option value="observe">Beobachten</option><option value="action_required">Handlungsbedarf</option><option value="critical">Kritisch</option></select></label><label>Fachliche Dokumentation<textarea name="note" rows="4" required></textarea></label><label>Folgemaßnahme<textarea name="nextAction" rows="2"></textarea></label><button class="primary">Serviceakte erstellen und abschließen</button></form>`);document.addEventListener('submit',async e=>{if(e.target.id!=='opportunity-complete-form')return;e.preventDefault();await api(`/api/partner-opportunities/${b.dataset.id}/complete`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Serviceakte erstellt und Ergebnis zurückgespielt');opportunityPage()},{once:true})});return}if(d.scope==='admin_light_overview'){$('#content').innerHTML=`<div class="page"><section class="hero"><div><span class="kicker">ANLÄSSE & OPPORTUNITIES</span><h1>Operative Übersicht.</h1><p>Admin Light sieht verarbeitete Ereignisse und entstandene Partnerchancen. Regeln, Schwellenwerte und Trigger-Konfiguration bleiben Admin Plus vorbehalten.</p></div></section><div class="kpis opportunity-kpis">${[['Ereignisse',d.kpis.events],['Betroffene Objekte',d.kpis.affected],['Relevante Objekte',d.kpis.relevant],['Opportunities',d.kpis.opportunities],['Service-Leads',d.kpis.serviceLeads]].map(([l,v])=>`<div class="card kpi"><span class="muted">${l}</span><div class="value">${v}</div></div>`).join('')}</div><div class="grid-2"><article class="card"><div class="card-head"><div><span class="kicker">EREIGNISSE</span><h3>Verarbeitete Anlässe</h3></div></div>${d.events.slice(0,10).map(x=>`<div class="campaign-row"><div><b>${esc(x.triggerName)}</b><small>${esc(x.region||x.state||'–')} · Schwere ${x.severity??'–'}</small></div><span class="status">${esc(statusLabel(x.processingStatus))}</span></div>`).join('')||'<p class="muted">Noch keine Ereignisse verarbeitet.</p>'}</article><article class="card"><div class="card-head"><div><span class="kicker">PARTNERCHANCEN</span><h3>Entstandene Opportunities</h3></div></div>${d.opportunities.slice(0,10).map(o=>`<div class="campaign-row"><div><b>${esc(o.triggerName)}</b><small>${esc(o.partnerName)} · ${esc(o.region)} · ${o.propertyCount} Objekte</small></div><span class="status">${esc(statusLabel(o.status))}</span></div>`).join('')||'<p class="muted">Noch keine Opportunities vorhanden.</p>'}</article></div></div>`;return}const readOnly=state.user.role!=='super_admin',defById=id=>d.definitions.find(x=>x.id===id),eventById=id=>d.events.find(x=>x.id===id),oppById=id=>d.opportunities.find(x=>x.id===id);$('#content').innerHTML=`<div class="page"><section class="hero opportunity-hero"><div><span class="kicker">EHV ANLASS- & OPPORTUNITY ENGINE</span><h1>Vom Ereignis zur qualifizierten Serviceakte.</h1><p>Relevanzbasiert, konfigurierbar, nachvollziehbar und mit serverseitiger Freigabe.</p></div>${readOnly?'':`<button class="primary" id="simulate-trigger">+ Sturm-Event simulieren</button>`}</section><div class="kpis opportunity-kpis">${[['Trigger-Events',d.kpis.events],['Betroffene Objekte',d.kpis.affected],['Relevant',d.kpis.relevant],['Unterdrückt',d.kpis.suppressed],['Opportunities',d.kpis.opportunities],['Service-Leads',d.kpis.serviceLeads]].map(([l,v])=>`<div class="card kpi"><span class="muted">${l}</span><div class="value">${v}</div></div>`).join('')}</div><section class="card conversion-card"><div class="card-head"><div><span class="kicker">CONVERSION-FLUSS</span><h3>Messbarer Anlassprozess</h3></div><span class="status">Queue-fähig · ${esc(d.queue.mode)}</span></div><div class="metric-strip">${[['Push-Rate',d.kpis.pushRate],['Open-Rate',d.kpis.openRate],['Response-Rate',d.kpis.responseRate],['Service-Lead-Rate',d.kpis.serviceLeadRate],['Abschlussrate',d.kpis.completedServiceRate]].map(([l,v])=>`<div><b>${v}%</b><small>${l}</small></div>`).join('')}</div></section><div class="opportunity-admin-grid"><article class="card"><div class="card-head"><div><span class="kicker">TRIGGER DEFINITIONS</span><h3>Regeln & Kontaktschutz</h3></div></div>${d.definitions.map(x=>`<div class="definition-row"><div><b>${esc(x.name)}</b><small>${esc(x.code)} · ${esc(x.category)}</small></div><label>Mindestscore<input class="definition-number" data-field="minimumRelevanceScore" data-id="${x.id}" type="number" value="${x.minimumRelevanceScore}" ${readOnly?'disabled':''}></label><label>Cooldown<input class="definition-number" data-field="cooldownDays" data-id="${x.id}" type="number" value="${x.cooldownDays}" ${readOnly?'disabled':''}></label><button class="${x.active?'status':'status high'} definition-toggle" data-id="${x.id}" data-active="${x.active}" ${readOnly?'disabled':''}>${x.active?'Aktiv':'Inaktiv'}</button></div>`).join('')}</article><article class="card"><div class="card-head"><div><span class="kicker">TRIGGER EVENTS</span><h3>Verarbeitete Ereignisse</h3></div></div>${d.events.slice(0,8).map(x=>`<div class="campaign-row"><div><b>${esc(defById(x.triggerDefinitionId)?.name||x.externalEventId)}</b><small>${esc(x.region||x.state)} · Schwere ${x.severity} · ${x.postalCodes.join(', ')}</small></div><span class="status">${esc(x.processingStatus)}</span></div>`).join('')||'<p class="muted">Noch kein Ereignis verarbeitet.</p>'}</article></div><section class="card" style="margin-top:18px"><div class="card-head"><div><span class="kicker">PARTNER OPPORTUNITIES</span><h3>Aggregierte Bedarfe und Conversion</h3></div></div><div class="table-wrap"><table><thead><tr><th>Anlass</th><th>Partner</th><th>Objekte</th><th>Hohe Priorität</th><th>Status</th></tr></thead><tbody>${d.opportunities.map(o=>`<tr><td><b>${esc(defById(o.triggerDefinitionId)?.name)}</b><br><small>${esc(eventById(o.triggerEventId)?.region||'')}</small></td><td>${esc((d.partners||[]).find(p=>p.id===o.partnerId)?.company||o.partnerId)}</td><td>${o.propertyCount}</td><td>${o.highPriorityCount}</td><td><span class="status ${o.status==='completed'?'':'invited'}">${esc(statusLabel(o.status))}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Noch keine Opportunity erzeugt.</td></tr>'}</tbody></table></div></section><section class="card score-audit" style="margin-top:18px"><div class="card-head"><div><span class="kicker">SCORE DETAILS & CUSTOMER ACTIONS</span><h3>Nachvollziehbare Entscheidungen</h3></div></div>${d.affectedProperties.slice(0,20).map(x=>{const action=d.customerActions.find(a=>a.affectedPropertyId===x.id);return `<details><summary><span><b>Objekt ${esc(x.propertyId)}</b><small>${esc(defById(x.triggerDefinitionId)?.name)} · ${esc(x.decision)}</small></span><strong>${x.scoreTotal}/100</strong></summary><div class="score-breakdown">${x.scoreBreakdown.map(s=>`<p><span>${esc(s.label)}</span><b>${s.points>0?'+':''}${s.points}</b></p>`).join('')||'<p>Keine Regel traf zu.</p>'}${x.suppressionReason?`<div class="source-note">Unterdrückt: ${esc(x.suppressionReason)}</div>`:''}${action&&!readOnly&&action.status==='proposed'?`<div class="customer-simulation"><b>Kundenreaktion simulieren</b><button data-response="ok" data-action="${action.id}">Alles in Ordnung</button><button data-response="unsure" data-action="${action.id}">Unsicher</button><button data-response="damage" data-action="${action.id}">Schaden festgestellt</button><button data-response="dismissed" data-action="${action.id}">Ablehnen</button></div>`:action?`<p>Kundenaktion: <b>${esc(action.status)} ${esc(action.response||'')}</b></p>`:''}</div></details>`}).join('')||'<p class="muted">Score-Details erscheinen nach der ersten Eventverarbeitung.</p>'}</section></div>`;if(readOnly)return;$('#simulate-trigger').onclick=()=>{modal('Sturm-Event simulieren',`<form id="trigger-event-form"><label>Trigger Definition<select name="triggerDefinitionId">${d.definitions.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`)}</select></label><div class="form-grid"><label>Quelle<input name="source" value="Weather Provider Simulation" required></label><label>Ereignis-ID<input name="externalEventId" value="STORM-${Date.now()}" required></label><label>Region<input name="region" value="Hamburg"></label><label>Schwere / Windgeschwindigkeit<input name="severity" type="number" value="85" min="0" max="200"></label></div><label>Betroffene PLZ, kommasepariert<input name="postalCodes" value="22301" required></label><button class="primary">Queue-Job anlegen und Testlauf starten</button></form>`);document.addEventListener('submit',async e=>{if(e.target.id!=='trigger-event-form')return;e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.postalCodes=f.postalCodes.split(',').map(x=>x.trim());await api('/api/trigger-events',{method:'POST',body:JSON.stringify(f)});closeModal();toast('Trigger idempotent verarbeitet');opportunityPage()},{once:true})};document.querySelectorAll('.definition-toggle').forEach(b=>b.onclick=async()=>{await api(`/api/trigger-definitions/${b.dataset.id}`,{method:'PATCH',body:JSON.stringify({active:b.dataset.active!=='true'})});opportunityPage()});document.querySelectorAll('.definition-number').forEach(i=>i.onchange=async()=>{await api(`/api/trigger-definitions/${i.dataset.id}`,{method:'PATCH',body:JSON.stringify({[i.dataset.field]:Number(i.value)})});toast('Trigger-Konfiguration gespeichert')});document.querySelectorAll('[data-response]').forEach(b=>b.onclick=async()=>{await api(`/api/customer-actions/${b.dataset.action}/respond`,{method:'POST',body:JSON.stringify({response:b.dataset.response})});toast('Kundenreaktion verarbeitet');opportunityPage()})};
