customers:async()=>{const d=await api('/api/customers');$('#content').innerHTML=`<div class="page"><div class="toolbar"><input id="search" placeholder="Kunden, Objekt-ID oder Adresse suchen …"><a class="outline" href="/api/export/properties.csv">Excel-Export</a></div><div class="card table-wrap"><table><thead><tr><th>Kunde</th><th>EHV-Objekt</th><th>Adresse</th><th>Objekt</th><th>Verkehrswert</th><th>Freigabe</th></tr></thead><tbody id="rows">${d.properties.map(p=>{const c=d.customers.find(x=>x.id===p.customerId);return `<tr><td><b>${esc(c?.name)}</b><br><small class="muted">${esc(c?.email)}</small></td><td>${p.ehvId}</td><td>${esc(p.address)}<br><small>${p.postalCode} ${p.city}</small></td><td>${p.type}<br><small>${p.area} m² · ${p.year}</small></td><td><b>${money(p.value)}</b></td><td><span class="status">Zugewiesen</span></td></tr>`}).join('')}</tbody></table></div></div>`;$('#search').oninput=e=>document.querySelectorAll('#rows tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()))},
cases:async()=>{const d=await api('/api/cases');$('#content').innerHTML=`<div class="page"><div class="toolbar"><input id="search" placeholder="Serviceakte durchsuchen …"><button class="primary" id="new-case">+ Servicefall</button></div><div class="card">${caseTable(d.cases,d.properties)}</div><div class="card table-wrap" style="margin-top:18px"><div class="card-head"><div><h3>Dokumentierte Serviceleistungen</h3><span class="muted">Für Support durch Admin Plus und Admin Light änderbar</span></div></div><table><thead><tr><th>Datum</th><th>Kunde / Objekt</th><th>Equipment</th><th>Service</th><th>Dokumente</th><th></th></tr></thead><tbody>${d.serviceRecords.map(record=>{const property=d.properties.find(x=>x.id===record.propertyId),customer=d.customers.find(x=>x.id===property?.customerId),equipment=d.equipment.find(x=>x.id===record.equipmentId);return `<tr><td>${new Date(record.date).toLocaleDateString('de-DE')}</td><td><b>${esc(customer?.name||'Kunde')}</b><br><small>${esc(property?.ehvId||record.propertyId)}</small></td><td>${esc(equipment?.label||record.equipmentId)}</td><td>${esc(serviceLabels[record.type]||record.type)}</td><td>${record.documents?.length||0}</td><td><button class="outline admin-service-record" data-service-record="${record.id}">Öffnen</button></td></tr>`}).join('')||'<tr><td colspan="6">Noch keine dokumentierten Serviceleistungen.</td></tr>'}</tbody></table></div><div class="card" style="margin-top:18px"><div class="card-head"><h3>Geschützte Upload-Dropzone</h3><span class="status">Virenscan-Adapter vorgesehen</span></div><p class="muted">Dokumente werden je Serviceakte gespeichert. In dieser Testfassung ist der produktive Object-Storage/AV-Scanner bewusst noch nicht verbunden.</p><div style="border:1px dashed #b8c9c3;border-radius:12px;padding:30px;text-align:center">Dateien hier ablegen oder Serviceakte öffnen</div></div></div>`;document.querySelectorAll('.admin-service-record').forEach(button=>button.onclick=()=>openServiceRecord(button.dataset.serviceRecord));$('#new-case').onclick=()=>modal('Neuen Servicefall anlegen',`<form id="case-form"><label>Objekt<select name="propertyId">${d.properties.map(p=>`<option value="${p.id}">${p.ehvId} · ${p.address}</option>`)}</select></label><label>Titel<input name="title" required></label><div class="form-grid"><label>Kategorie<input name="category" required></label><label>Priorität<select name="priority"><option value="medium">Normal</option><option value="high">Hoch</option><option value="low">Niedrig</option></select></label></div><button class="primary">Servicefall anlegen</button></form>`);setTimeout(()=>$('#case-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));await api('/api/cases',{method:'POST',body:JSON.stringify(f)});closeModal();toast('Servicefall angelegt');render('cases')},0)},
sales:async()=>{const d=await api('/api/sales');$('#content').innerHTML=`<div class="page"><section class="grid-2"><div class="card"><div class="card-head"><h3>Verkaufsbereitakten</h3><span class="status">Maklerbereich</span></div><table><thead><tr><th>Objekt</th><th>Vollständigkeit</th><th>Angebotspreis</th><th>Status</th></tr></thead><tbody>${d.salesFiles.map(s=>{const p=d.properties.find(x=>x.id===s.propertyId);return `<tr><td><b>${p?.ehvId}</b><br><small>${p?.address}</small></td><td>${s.completeness}%<div class="progress"><i style="width:${s.completeness}%"></i></div></td><td>${money(s.askingPrice)}</td><td><span class="status invited">In Prüfung</span></td></tr>`}).join('')||'<tr><td colspan="4" class="empty">Keine freigegebenen Verkaufsakten.</td></tr>'}</tbody></table></div><div class="card"><div class="card-head"><h3>Verkehrswert validieren</h3></div><form id="valuation-form"><label>Objekt<select name="propertyId">${d.properties.map(p=>`<option value="${p.id}">${p.ehvId}</option>`)}</select></label><label>Maklerwert in EUR<input type="number" name="value" required></label><label>Stichtag<input type="date" name="effectiveDate" required value="${new Date().toISOString().slice(0,10)}"></label><label>Begründung<textarea name="note" rows="3"></textarea></label><button class="primary">Historisiert speichern</button></form></div></section><div class="card" style="margin-top:18px"><div class="card-head"><h3>Bewertungshistorie</h3><span class="muted">Unveränderliche fachliche Historie</span></div><table><thead><tr><th>Stichtag</th><th>Objekt</th><th>Quelle</th><th>Wert</th><th>Notiz</th></tr></thead><tbody>${d.valuations.slice().reverse().map(v=>`<tr><td>${v.effectiveDate}</td><td>${d.properties.find(p=>p.id===v.propertyId)?.ehvId||v.propertyId}</td><td>${v.source}</td><td><b>${money(v.value)}</b></td><td>${esc(v.note)}</td></tr>`).join('')}</tbody></table></div></div>`;$('#valuation-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));await api('/api/valuations',{method:'POST',body:JSON.stringify(f)});toast('Maklerwert historisiert');render('brokerCustomers')}},
